<?php
namespace App\Livewire\LMS\Students;
use App\Models\ClassEnrollment; use App\Models\School; use App\Models\SchoolClass; use App\Models\Student; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException; use Jantinnerezo\LivewireAlert\Facades\LivewireAlert; use Livewire\Attributes\Layout; use Livewire\Component; use Livewire\WithPagination; use Throwable;
#[Layout('layouts.lms')]
class Index extends Component { use AuthorizesRequests; use WithPagination; public bool $showFormModal=false,$showDeleteModal=false; public ?int $editingId=null,$deletingId=null; public string $studentId='',$admissionNumber='',$firstName='',$middleName='',$lastName='',$dateOfBirth='',$gender='',$admissionDate='',$schoolClassId='',$status='active';
public function mount():void{$this->authorize('viewAny',Student::class);} public function create():void{$this->authorize('create',Student::class);$this->resetForm();$this->admissionDate=now()->toDateString();$this->showFormModal=true;} public function edit(Student $student):void{$this->authorize('update',$student);$this->editingId=$student->id;$this->studentId=$student->student_id;$this->admissionNumber=$student->admission_number;$this->firstName=$student->first_name;$this->middleName=$student->middle_name??'';$this->lastName=$student->last_name;$this->dateOfBirth=$student->date_of_birth->toDateString();$this->gender=$student->gender;$this->admissionDate=$student->admission_date->toDateString();$this->schoolClassId=(string)$student->enrollments()->where('status','active')->value('school_class_id');$this->status=$student->status;$this->showFormModal=true;}
public function save():void{$student=$this->editingId?Student::findOrFail($this->editingId):null;$this->authorize($student?'update':'create',$student??Student::class);$schoolId=$student?->school_id??School::query()->value('id');abort_unless($schoolId,422,'Configure a school before adding a student.');try{$data=$this->validate(['studentId'=>['required','string','max:50',Rule::unique('students','student_id')->ignore($student?->id)],'admissionNumber'=>['required','string','max:50',Rule::unique('students','admission_number')->ignore($student?->id)],'firstName'=>['required','string','max:100'],'middleName'=>['nullable','string','max:100'],'lastName'=>['required','string','max:100'],'dateOfBirth'=>['required','date','before:today'],'gender'=>['required','in:male,female,other'],'admissionDate'=>['required','date'],'schoolClassId'=>['nullable','integer','exists:school_classes,id'],'status'=>['required','in:active,graduated,transferred,withdrawn,suspended']]);DB::transaction(function()use($student,$schoolId,$data){$record=Student::updateOrCreate(['id'=>$student?->id],['school_id'=>$schoolId,'student_id'=>$data['studentId'],'admission_number'=>$data['admissionNumber'],'first_name'=>$data['firstName'],'middle_name'=>$data['middleName']?:null,'last_name'=>$data['lastName'],'date_of_birth'=>$data['dateOfBirth'],'gender'=>$data['gender'],'admission_date'=>$data['admissionDate'],'status'=>$data['status']]);if($data['schoolClassId']){ClassEnrollment::where('student_id',$record->id)->where('status','active')->where('school_class_id','!=',$data['schoolClassId'])->update(['status'=>'transferred','left_at'=>now()->toDateString()]);ClassEnrollment::updateOrCreate(['student_id'=>$record->id,'school_class_id'=>$data['schoolClassId']],['enrolled_at'=>$data['admissionDate'],'status'=>'active','left_at'=>null]);}});$this->showFormModal=false;$this->resetForm();LivewireAlert::title($student?'Student updated':'Student enrolled')->success()->asToast()->position('top-end')->show();}catch(ValidationException $e){LivewireAlert::title('Check the form')->error()->asToast()->position('top-end')->show();throw $e;}catch(Throwable $e){report($e);LivewireAlert::title('Unable to save student')->error()->asToast()->position('top-end')->show();}}
public function confirmDelete(Student $student):void{$this->authorize('delete',$student);$this->deletingId=$student->id;$this->showDeleteModal=true;} public function delete():void{$student=Student::findOrFail($this->deletingId);$this->authorize('delete',$student);try{$student->delete();$this->showDeleteModal=false;$this->deletingId=null;LivewireAlert::title('Student archived')->success()->asToast()->position('top-end')->show();}catch(Throwable $e){report($e);LivewireAlert::title('Unable to archive student')->error()->asToast()->position('top-end')->show();}} public function closeModals():void{$this->showFormModal=false;$this->showDeleteModal=false;$this->resetForm();$this->resetErrorBag();} private function resetForm():void{$this->reset(['editingId','deletingId','studentId','admissionNumber','firstName','middleName','lastName','dateOfBirth','gender','admissionDate','schoolClassId','status']);$this->status='active';$this->resetValidation();} public function render(){return view('livewire.lms.students.index',['students'=>Student::with(['enrollments.schoolClass'])->latest()->paginate(15),'classes'=>SchoolClass::where('status','active')->orderBy('name')->get()]);}}
